24:-- mud spit lower left
345:mudD = pile{{"raw umber",1},{"red earth",0.3},{"bone black",0.25},{"lead white",0.25},{"green earth",0.3}}
346:mudM = pile{{"raw umber",1},{"yellow ochre",0.4},{"red earth",0.2},{"lead white",0.6},{"smalt",0.2}}
348:work(spit2, {hand="body", pile=mudD, angle=function(x,y) return 0.12 + (x/1000)*0.3 end, angle_jitter=0.1, coverage=3, length={20,70}, fill=true})
349:-- a lighter muddy top edge where the bank catches the sky
352:work(lip, {hand="detail", pile=mudM, angle=0.2, coverage=1.2, pressure={0.3,0.6}})
355:mudDD = pile{{"raw umber",1},{"bone black",0.35},{"smalt",0.25},{"red earth",0.15}}
357:work(inner * mask(function(x,y) return clamp((y-580)/40,0,1) end), {hand="body", pile=mudDD, angle=0.15, angle_jitter=0.1, coverage=2, length={30,90}})
429:mudDD2 = pile{{"raw umber",1},{"bone black",0.3},{"smalt",0.2},{"red earth",0.2},{"lead white",0.12}}
432:work(sp, {hand="body", pile=mudDD2, angle=function(x,y) return 0.1 + x/2000 end, angle_jitter=0.08, coverage=2.5, length={30,90}, fill=true, clip=spit2})
433:-- wet sheen streaks on the mud, following the bank
484:spit3 = outline{{-30,574},{40,568},{110,566},{190,575},{260,594},{320,620},{370,652},{400,700,"c"},{-30,700,"c"}, closed=true, char="firm", amount=0.5, seed=95}:mask()
485:mudA = pile{{"raw umber",1},{"bone black",0.3},{"red earth",0.25},{"smalt",0.15},{"lead white",0.1}}
486:work(spit3, {hand="body", pile=mudA, angle=function(x,y) return 0.12 + x/2500 end, angle_jitter=0.08, coverage=3, length={30,90}, fill=true, edge={found=0.5, soft=0.5, period=50}})
490:work(bot, {hand="body", pile=mudA, angle=0.1, coverage=3, fill=true, length={30,80}, clip=rect(-10,600,420,80)*spit3:grow(1)})
545:mudGlaze = pile{{"bone black",0.6},{"raw umber",1},{"smalt",0.2}, medium=0.5}
547:work(corner, {hand="glaze", pile=mudGlaze, angle=0.15, coverage=1.2, clip=spit3})
559:mudCool = pile{{"raw umber",1},{"bone black",0.3},{"smalt",0.45},{"lead white",0.3},{"red earth",0.1}}
560:mudWarm = pile{{"raw umber",1},{"bone black",0.35},{"red earth",0.35},{"lead white",0.08}}
564:o.pile = mudCool; work(upper, o)
565:o.pile = mudWarm; work(lower, o)
569:mudDark = pile{{"raw umber",1},{"bone black",0.5},{"smalt",0.2},{"red earth",0.2}}
570:local o = {hand="body", tool="filbert 8", pile=mudDark, angle=function(x,y) return 0.12 + x/2500 end, angle_jitter=0.1, coverage=3.5, length={25,80}, fill=true, clip=spit3, load=0.9}
576:puddleP = pile{{"lead white",2.2},{"yellow ochre",0.5},{"chrome yellow",0.15},{"red earth",0.15},{"smalt",0.2},{"raw umber",0.15}}
577:puddleP2 = pile{{"lead white",1.6},{"smalt",0.7},{"red earth",0.3},{"raw umber",0.4}}
578:-- puddles, drawn as thin flat lenses
582:work(p1 + p2, {hand="detail", pile=puddleP, angle=0.05, coverage=2, fill=true, clip=true})
583:work(p3, {hand="detail", pile=puddleP2, angle=0.05, coverage=2, fill=true, clip=true})
650:-- dull the puddles: thin glaze of mud over them
651:puddleGlaze = pile{{"raw umber",1},{"smalt",0.3},{"red earth",0.2}, medium=0.55}
653:work(pz*spit3, {hand="glaze", tool="filbert 8", pile=puddleGlaze, angle=0.05, coverage=1.3, clip=spit3})

