pz2 = outline{{130,626},{175,621},{215,625},{170,630}, closed=true, char="soft", amount=0.4, seed=122}:mask()
work(pz2:grow(0.5), {hand="detail", tool={kind="round", width=2.5}, pile=pudCool2, angle=0.03, coverage=1.5, pressure={0.3,0.5}, fill=true, clip=true})' ; bin/easel look --crop 0,580,260,667

bin/easel do 'local g = pile{{"lead white",1},{"chrome yellow",0.3},{"yellow ochre",0.3},{"red earth",0.08}}
local r = brush{kind="round", width=1.6, point=0.7}
r:reload(g, 0.35)
r:stroke({{140,624.5},{165,622.8},{195,623.5}}, {pressure={0.35,0.15}, ramps={0.2,0.4}, clip=pz2})
r:reload(g, 0.3)
r:stroke({{55,605},{78,603.8},{100,604.5}}, {pressure={0.3,0.12}, ramps={0.2,0.4}, clip=pz1})'; bin/easel look --crop 0,580,260,667; bin/easel look
